package cn.ping.launcher;
import android.app.*;import android.os.*;import android.content.*;import android.graphics.*;import android.graphics.drawable.*;import android.content.res.ColorStateList;import android.view.*;import android.widget.*;import java.util.concurrent.*;
public class HiddenGateActivity extends Activity {
 ExecutorService worker=Executors.newSingleThreadExecutor();TextView title,detail,error,submit;PinDots dots;String first="";final StringBuilder pin=new StringBuilder();int stage;boolean busy,dead;int expected;
 int dp(float x){return Math.round(x*getResources().getDisplayMetrics().density);}
 TextView label(String s,int size,int color){TextView v=new TextView(this);v.setText(s);v.setTextSize(size);v.setTextColor(color);v.setGravity(Gravity.CENTER);return v;}
 GradientDrawable round(int color,int radius){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(radius));return d;}
 public void onCreate(Bundle b){super.onCreate(b);getWindow().addFlags(WindowManager.LayoutParams.FLAG_SECURE);getWindow().setStatusBarColor(0xff14283c);getWindow().setNavigationBarColor(0xff254b5d);getWindow().setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_STATE_ALWAYS_HIDDEN);stage=HiddenVault.configured(this)?0:1;expected=getSharedPreferences("vault",0).getInt("length",0);
 ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);scroll.setVerticalScrollBarEnabled(false);scroll.setBackground(new GradientDrawable(GradientDrawable.Orientation.TL_BR,new int[]{0xff14283c,0xff254b5d}));scroll.setOnApplyWindowInsetsListener((v,i)->{scroll.setPadding(i.getSystemWindowInsetLeft(),i.getSystemWindowInsetTop(),i.getSystemWindowInsetRight(),i.getSystemWindowInsetBottom());return i;});LinearLayout outer=new LinearLayout(this);outer.setGravity(Gravity.CENTER);scroll.addView(outer);LinearLayout box=new LinearLayout(this);box.setOrientation(1);box.setGravity(Gravity.CENTER_HORIZONTAL);box.setPadding(dp(24),dp(18),dp(24),dp(20));outer.addView(box,new LinearLayout.LayoutParams(Math.min(getResources().getDisplayMetrics().widthPixels,dp(400)),-2));setContentView(scroll);scroll.requestApplyInsets();TextView back=label("‹ 返回桌面",14,0xffb7cdd8);back.setGravity(Gravity.LEFT|Gravity.CENTER_VERTICAL);back.setPadding(dp(4),0,0,0);back.setOnClickListener(v->finish());box.addView(back,new LinearLayout.LayoutParams(-1,dp(40)));
 View lock=new LockMark();LinearLayout.LayoutParams lockParams=new LinearLayout.LayoutParams(dp(42),dp(42));lockParams.topMargin=dp(8);lockParams.bottomMargin=dp(14);box.addView(lock,lockParams);title=label("",26,Color.WHITE);title.setTypeface(null,Typeface.BOLD);box.addView(title);detail=label("",13,0xffaec6d2);detail.setPadding(dp(10),dp(10),dp(10),dp(4));detail.setLineSpacing(dp(2),1);box.addView(detail,new LinearLayout.LayoutParams(-1,-2));dots=new PinDots();box.addView(dots,new LinearLayout.LayoutParams(-1,dp(48)));error=label("",12,0xffffb8bd);error.setMaxLines(2);box.addView(error,new LinearLayout.LayoutParams(-1,dp(38)));
 for(int row=0;row<4;row++){LinearLayout line=new LinearLayout(this);line.setGravity(Gravity.CENTER);for(int col=0;col<3;col++){final int index=row*3+col;String value=index<9?String.valueOf(index+1):index==9?"⌫":index==10?"0":"›";TextView key=label(value,index<9||index==10?29:27,Color.WHITE);key.setTypeface(Typeface.create("sans-serif-light",0));key.setBackground(new RippleDrawable(ColorStateList.valueOf(0x44ffffff),round(index==11?0xff397f7a:0x14ffffff,36),round(Color.WHITE,36)));LinearLayout.LayoutParams params=new LinearLayout.LayoutParams(0,dp(64),1);params.setMargins(dp(8),dp(6),dp(8),dp(6));line.addView(key,params);key.setContentDescription(index==9?"删除一位":index==11?"确认密码":value);key.setOnClickListener(v->{if(busy)return;key.performHapticFeedback(HapticFeedbackConstants.KEYBOARD_TAP);if(index==9){if(pin.length()>0)pin.deleteCharAt(pin.length()-1);changed();}else if(index==11)accept();else digit(value);});if(index==11)submit=key;}box.addView(line,new LinearLayout.LayoutParams(-1,-2));}TextView footer=label("仅在本机验证 · 离开后重新锁定",11,0xff8cabb9);footer.setPadding(0,dp(16),0,0);box.addView(footer);update();}
 void digit(String value){if(pin.length()>=12)return;pin.append(value);error.setText("");changed();if(stage==0&&expected>=6&&pin.length()==expected)accept();}
 void changed(){dots.invalidate();dots.setContentDescription("已输入 "+pin.length()+" 位密码");submit.setAlpha(pin.length()>=6?1f:.4f);}
 void clearPin(){pin.setLength(0);changed();}
 void update(){title.setText(stage==0?"解锁隐藏空间":stage==1?"设置隐藏密码":"再次确认密码");detail.setText(stage==0?"输入密码，进入你的专属空间":stage==1?"设置 6–12 位数字，完成后点右下角确认\n请牢记密码，目前不支持找回":"再输入一次刚才的密码");clearPin();}
 void accept(){if(busy)return;String value=pin.toString();if(!HiddenVault.valid(value)){error.setText("请输入 6–12 位数字");return;}android.content.SharedPreferences p=getSharedPreferences("vault",0);if(stage==0&&p.getLong("blocked",0)>System.currentTimeMillis()){error.setText("尝试过多，请稍后再试");clearPin();return;}if(stage==1){first=value;stage=2;error.setText("");update();return;}if(stage==2&&!value.equals(first)){error.setText("两次密码不一致，请重新确认");clearPin();return;}busy=true;submit.setEnabled(false);final int operation=stage;worker.execute(()->{boolean ok=false;try{if(operation==0)ok=HiddenVault.verify(this,value);else{HiddenVault.set(this,value);ok=true;}}catch(Exception ignored){}final boolean success=ok;runOnUiThread(()->{if(dead)return;busy=false;submit.setEnabled(true);clearPin();if(!success){int fails=p.getInt("fails",0)+1;p.edit().putInt("fails",fails>=5?0:fails).putLong("blocked",fails>=5?System.currentTimeMillis()+30000:0).apply();error.setText(operation==0?"密码错误，连续 5 次错误将暂停 30 秒":"保存失败，请重试");dots.animate().translationX(dp(8)).setDuration(50).withEndAction(()->dots.animate().translationX(0).setDuration(80).start()).start();return;}p.edit().putInt("fails",0).putLong("blocked",0).apply();if(operation==0){expected=value.length();p.edit().putInt("length",expected).apply();}if(operation==0&&getIntent().getBooleanExtra("change",false)){stage=1;first="";error.setText("");update();return;}first="";if(!getIntent().getBooleanExtra("change",false))startActivity(new Intent(this,HiddenAppsActivity.class).putExtra("quick",getIntent().getBooleanExtra("quick",false)).putExtra("ticket",HiddenVault.grant()));else Toast.makeText(this,"隐藏密码已更新",0).show();finish();});});}
 protected void onStop(){super.onStop();if(dots!=null)clearPin();if(stage==2){first="";stage=1;if(!isFinishing())update();}}
 protected void onDestroy(){dead=true;first="";pin.setLength(0);worker.shutdownNow();super.onDestroy();}
 class PinDots extends View{Paint paint=new Paint(3);PinDots(){super(HiddenGateActivity.this);}protected void onDraw(Canvas c){int count=stage==0&&expected>=6?expected:Math.max(6,pin.length());float step=Math.min(dp(25),(getWidth()-dp(32))/(float)count),start=getWidth()/2f-(count-1)*step/2;for(int i=0;i<count;i++){paint.setStyle(i<pin.length()?Paint.Style.FILL:Paint.Style.STROKE);paint.setStrokeWidth(dp(1.3f));paint.setColor(i<pin.length()?0xffc4e8df:0xff6f95a6);c.drawCircle(start+i*step,getHeight()/2f,dp(4.5f),paint);}}}
 class LockMark extends View{Paint paint=new Paint(3);LockMark(){super(HiddenGateActivity.this);}protected void onDraw(Canvas c){c.save();c.scale(getWidth()/32f,getHeight()/32f);paint.setColor(0xffb0d9d2);paint.setStyle(Paint.Style.STROKE);paint.setStrokeWidth(1.6f);c.drawRoundRect(6,14,26,29,4,4,paint);c.drawArc(10,3,22,23,180,180,false,paint);paint.setStrokeCap(Paint.Cap.ROUND);c.drawLine(16,20,16,23,paint);c.restore();}}
}
